// Create a new RW lock and track its state via attributes for later stubs
CRYPTO_RWLOCK *lock = CRYPTO_THREAD_lock_new();
if (!lock) { FUZZ_BAIL(); }
// Track reader count and writer-held flag in fuzzer attrs
FUZZ_SET_ATTR_INT(lock, "readers", 0);
FUZZ_SET_ATTR_INT(lock, "writer", 0);
// Provide lock back to the pool as a persistent object

// Enforce that we are not currently holding a writer lock
int writer = FUZZ_GET_ATTR_INT(lock, "writer");
if (writer) { FUZZ_BAIL(); }
int ok = CRYPTO_THREAD_read_lock(lock);
if (!ok) { FUZZ_BAIL(); }
// Increment reader count attribute
int readers = FUZZ_GET_ATTR_INT(lock, "readers");
FUZZ_SET_ATTR_INT(lock, "readers", readers + 1);
// Return the lock so it remains available for subsequent stubs

// Enforce that no readers or writers currently hold the lock (single-thread model)
int readers = FUZZ_GET_ATTR_INT(lock, "readers");
int writer = FUZZ_GET_ATTR_INT(lock, "writer");
if (readers != 0 || writer != 0) { FUZZ_BAIL(); }
int ok = CRYPTO_THREAD_write_lock(lock);
if (!ok) { FUZZ_BAIL(); }
// Mark writer-held
FUZZ_SET_ATTR_INT(lock, "writer", 1);
// Return the lock so it remains available

// Determine which mode is held and enforce that the lock is currently held
int readers = FUZZ_GET_ATTR_INT(lock, "readers");
int writer = FUZZ_GET_ATTR_INT(lock, "writer");
if (readers <= 0 && writer == 0) { FUZZ_BAIL(); }
int ok = CRYPTO_THREAD_unlock(lock);
if (!ok) { FUZZ_BAIL(); }
// Update our tracked state
if (writer) {
    FUZZ_SET_ATTR_INT(lock, "writer", 0);
} else {
    FUZZ_SET_ATTR_INT(lock, "readers", readers - 1);
}
// Keep the lock available

// Only free when not held by any reader/writer (tracked by attributes)
int readers = FUZZ_GET_ATTR_INT(lock, "readers");
int writer = FUZZ_GET_ATTR_INT(lock, "writer");
