import random
import string

HEX_DIGITS = "0123456789abcdefABCDEF"
SEP_CANDIDATES = [
    ':', ' ', '-', ',', ';', '\t', '\n', '_', '.', '/', '\\'
]

# Build a valid hex string possibly with separators, suitable for
# OPENSSL_hexstr2buf_ex (with arbitrary sep) and OPENSSL_hexstr2buf (no sep).
# Also useful as the hex parameter for PEM_dek_info (expects hex-like params).

def _random_sep(rng):
    # Return a single ASCII separator character; sometimes choose none.
    if rng.random() < 0.35:
        return None
    # Pick from common separators, sometimes pick an arbitrary ASCII non-hex.
    if rng.random() < 0.8:
        return rng.choice(SEP_CANDIDATES)
    # arbitrary non-hex ASCII in 0..0x7F
    while True:
        c = chr(rng.randrange(0, 0x7F))
        if c not in string.ascii_letters and c not in string.digits:
            return c


def _make_hex_chunk(rng, length):
    return ''.join(rng.choice(HEX_DIGITS) for _ in range(length))


def _insert_separators(rng, hexstr, sep):
    if not sep:
        return hexstr
    # Insert the same separator at randomized positions ensuring overall size constraint.
    out = []
    for i, ch in enumerate(hexstr):
        out.append(ch)
        # With some probability after pairs, insert a separator
        if (i % 2 == 1) and rng.random() < 0.3:
            out.append(sep)
    # Also maybe add leading/trailing separators
    if rng.random() < 0.1:
        out.insert(0, sep)
    if rng.random() < 0.1:
        out.append(sep)
    return ''.join(out)


def _make_even_length_hex(rng, min_bytes, max_bytes):
    # Choose a byte length; ensure within fuzz stub limits (<=512 input size)
    nbytes = rng.randint(min_bytes, max_bytes)
    return _make_hex_chunk(rng, nbytes * 2)


def _variant_plain_compact(rng):
    # Compact even-length hex string, good for OPENSSL_hexstr2buf
    size_choice = rng.random()
    if size_choice < 0.2:
        nbytes = 0
    elif size_choice < 0.6:
        nbytes = rng.randint(1, 64)
    else:
        nbytes = rng.randint(65, 200)
    return _make_hex_chunk(rng, nbytes * 2)


def _variant_with_separators(rng):
    sep = _random_sep(rng)
    # Ensure underlying raw hex bytes range (restrict so final with seps <=512)
    # Reserve space for separators roughly 1/3 of pair positions.
    max_pairs = 256  # 512 hex chars -> 256 bytes (without seps)
    nbytes = rng.randint(1, max_pairs)
    base = _make_hex_chunk(rng, nbytes * 2)
    with_seps = _insert_separators(rng, base, sep)
    # If too long, trim separators to fit 512
    if len(with_seps) > 512:
        with_seps = with_seps[:512]
        # Avoid truncating mid-separator sequence: no special need; sep is single char
    return with_seps


def _variant_odd_length(rng):
    # Some APIs accept odd hex length by treating a leading nibble as a full byte
    # For OpenSSL, odd-length without separators is valid; keep within 512.
    n = rng.randint(1, 511)  # odd count of hex chars
    if n % 2 == 0:
        n -= 1
    return _make_hex_chunk(rng, n)


def _variant_iv_like(rng):
    # Useful for PEM_dek_info IV: 16 bytes (32 hex chars) typical for AES-128-CBC
    nbytes = rng.choice([16, 8, 32])  # try common IV sizes (though PEM only uses text)
    base = _make_hex_chunk(rng, nbytes * 2)
    # maybe uppercase to vary
    if rng.random() < 0.5:
        base = base.upper()
    return base


def _variant_mixed_case_and_seps(rng):
    sep = _random_sep(rng)
    nbytes = rng.randint(1, 200)
    base = _make_hex_chunk(rng, nbytes * 2)
    # randomize case
    chars = []
    for ch in base:
        if ch in string.ascii_letters and rng.random() < 0.5:
            chars.append(ch.upper())
        else:
            chars.append(ch.lower())
    base = ''.join(chars)
    return _insert_separators(rng, base, sep)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose a generation strategy to exercise different code paths
    strategies = [
        _variant_plain_compact,
        _variant_with_separators,
        _variant_odd_length,
        _variant_iv_like,
        _variant_mixed_case_and_seps,
    ]
    weights = [0.3, 0.3, 0.15, 0.15, 0.1]

    strat = rng.choices(strategies, weights=weights, k=1)[0]
    s = strat(rng)

    # Ensure not exceeding 512 chars to satisfy stub truncation, and overall cap 4096 bytes
    if len(s) > 512:
        s = s[:512]

    # Sometimes add a NUL terminator explicitly (C++ std::string doesn't need it, but harmless)
    if rng.random() < 0.05 and len(s) < 511:
        s = s + "\x00"

    # Return as bytes (UTF-8 ASCII-safe)
    b = s.encode('ascii', errors='ignore')
    if len(b) > 4096:
        b = b[:4096]
    return b
